(sel, r) => {
    for (const a of pref[sel] || ['L']) {
      const up = a.length > 1 && a.endsWith('B'), x = xs[up ? a.slice(0, -1) : a](r.w);
      if (!(x >= S.l)) continue;
      const y0 = top, y1 = H - S.b - 2 - r.h;
      for (let i = 0; ; i++) {
        const y = up ? y1 - i * 6 : y0 + i * 6;
        if (y < y0 || y > y1) break;
        const c = { x, y, w: r.w, h: r.h };
        if (free(c)) return c;
      }
    }
    return null;
  }
